import java.util.Scanner;

public class Main {
    public static void main(String[] args) {
        Scanner sc = new Scanner(System.in);
        long x = sc.nextLong();
        long y = sc.nextLong();
        long n = sc.nextLong();
        double ratio = (double) x / y;
        long bestNum = 1;
        long bestDen = 1;
        double minDiff = 1e9;
        double epsilon = 1e-25;

        if (y <= bestDen) {
            System.out.println(x + "/" + y);
            sc.close();
            return;
        }

        for (long i = 1; i <= n; ++i) {
            double val = ratio * i;
            long a1 = (long) Math.floor(val);
            long a2 = (long) Math.ceil(val);
            double diff1 = Math.abs(ratio - (double) a1 / i);
            if (diff1 < minDiff - epsilon) {
                minDiff = diff1;
                bestNum = a1;
                bestDen = i;
            }
            double diff2 = Math.abs((double) a2 / i - ratio);
            if (diff2 < minDiff - epsilon) {
                minDiff = diff2;
                bestNum = a2;
                bestDen = i;
            }
        }
        System.out.println(bestNum + "/" + bestDen);
        sc.close();
    }
}
